	}
	for _, r := range task.Requirements {
		fmt.Fprintf(&b, "- %s\n", r)
	}
	fmt.Fprintln(&b, "\nImplementation steps:")
	for _, step := range task.Steps {
		fmt.Fprintf(&b, "- %s\n", step)
	}
	fmt.Fprintln(&b, "\nExpected evidence:")
	for _, evidence := range task.Evidence {
