func renderExecuteQueue(currentTaskID string, queue []ExecutePlanTask) string {
	if len(queue) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("\n## Ordered Sprint Execution Queue\n\n")
	b.WriteString("This agent session owns the complete ordered queue below. Execute only the current task during this turn; UltraPlan will checkpoint its evidence before advancing the same session.\n\n")
	for index, task := range queue {
		marker := "queued"
		if task.ID == currentTaskID {
			marker = "current"
		}
		fmt.Fprintf(&b, "%d. [%s] `%s` — %s\n", index+1, marker, task.ID, task.Name)
	}
	return b.String()
}

func filterExecuteQueue(tasks []ExecutePlanTask, taskID string) []ExecutePlanTask {
	if taskID == "" {
		return append([]ExecutePlanTask(nil), tasks...)
	}
	selected := taskByID(tasks, taskID)
	if selected.ID == "" {
		return nil
	}
	return []ExecutePlanTask{selected}
}

func executeQueueFromState(records []ExecuteTaskRecord, tasks []ExecutePlanTask, taskID string) []ExecutePlanTask {
	queue := make([]ExecutePlanTask, 0, len(records))
	for _, record := range records {
		if taskID != "" && record.ID != taskID {
			continue
		}
		if record.Status == ExecuteTaskComplete || record.Status == ExecuteTaskDeferred {
			continue
		}
		if task := taskByID(tasks, record.ID); task.ID != "" {
			queue = append(queue, task)
		}
	}
	return queue
}

func reusableExecuteSession(records []ExecuteTaskRecord, taskID, model string) string {
	sessionID := ""
	for _, record := range records {
		if taskID != "" && record.ID != taskID {
			continue
		}
		if record.Runtime != nil && record.Runtime.Model == model && record.Runtime.SessionID != "" {
			sessionID = record.Runtime.SessionID
		}
	}
	return sessionID
}

func WriteExecuteSummary(root string, sp Sprint, state ExecuteRunState) error {
	path, err := resolveSprintContained(root, sp, ArtifactRelPath(sp, StageExecute))
	if err != nil {
		return err
	}
	var b strings.Builder
	fmt.Fprintf(&b, "# Execute Summary\n\nPlan: `%s`\nRun state: `%s`\n\n", state.PlanPath, ExecuteRunStateRelPath(sp))
	counts := map[ExecuteTaskStatus]int{}
	for _, task := range state.Tasks {
		counts[task.Status]++
	}
	fmt.Fprintln(&b, "## Task Counts")
	fmt.Fprintln(&b)
	for _, status := range ExecuteTaskStatuses() {
		fmt.Fprintf(&b, "- %s: %d\n", status, counts[status])
	}
	fmt.Fprintln(&b, "\n## Tasks")
	fmt.Fprintln(&b)
	for _, task := range state.Tasks {
		fmt.Fprintf(&b, "- `%s` %s: %s (attempts: %d)\n", task.ID, task.Status, task.Identity.Name, task.Attempts)
		for _, evidence := range task.Evidence {
			fmt.Fprintf(&b, "  - evidence: %s %s\n", evidence.Kind, evidence.Summary)
		}
		for _, diagnostic := range task.Diagnostics {
			fmt.Fprintf(&b, "  - diagnostic: %s %s\n", diagnostic.Code, diagnostic.Message)
		}
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(path, []byte(b.String()), 0o644)
}

func ArtifactExecuteRelPath(s Sprint) string { return ArtifactRelPath(s, StageExecute) }

func taskByID(tasks []ExecutePlanTask, id string) ExecutePlanTask {
	for _, task := range tasks {
		if task.ID == id {
			return task
		}
	}
	return ExecutePlanTask{}
}

func reconcileExecuteState(existing ExecuteRunState, planned []ExecuteTaskRecord, now time.Time) ExecuteRunState {
	byID := map[string]ExecuteTaskRecord{}
	for _, task := range existing.Tasks {
		if task.Status == ExecuteTaskRunning {
			task.Status = ExecuteTaskFailed
			task.CompletedAt = &now
			task.Diagnostics = append(task.Diagnostics, ExecuteDiagnostic{Code: "stale-running", Message: "recovered stale running task on resume", At: now})
		}
		byID[task.ID] = task
	}
	for i, task := range planned {
		if old, ok := byID[task.ID]; ok {
			planned[i] = old
		}
	}
	existing.Tasks = planned
	existing.UpdatedAt = now
	return existing
}

func runtimeSummary(run pruntime.Result, selection ExecuteModelSelection) *ExecuteRuntimeSummary {
	return &ExecuteRuntimeSummary{RunID: run.RunID, SessionID: run.SessionID, Model: selection.Model, ModelSource: selection.Source, PermissionSummary: run.Permissions.Mode, ValidationSummary: fmt.Sprintf("configured=%t passed=%t failures=%d", run.Validation.Configured, run.Validation.Passed, run.Validation.Failures), UsageSummary: formatRuntimeUsage(run.Usage), OmissionReason: "raw runtime payloads omitted"}
}

func formatRuntimeUsage(usage pruntime.Usage) string {
	var parts []string
	appendKnown := func(name string, known bool, value int64) {
		if known {
			parts = append(parts, fmt.Sprintf("%s=%d", name, value))
		}
	}
	appendKnown("input", usage.InputTokensKnown, usage.InputTokens)
	appendKnown("output", usage.OutputTokensKnown, usage.OutputTokens)
	appendKnown("reasoning", usage.ReasoningTokensKnown, usage.ReasoningTokens)
	appendKnown("cache_read", usage.CacheReadTokensKnown, usage.CacheReadTokens)
	appendKnown("cache_write", usage.CacheWriteTokensKnown, usage.CacheWriteTokens)
	appendKnown("total", usage.TotalTokensKnown, usage.TotalTokens)
	appendKnown("turns", usage.TurnsKnown, usage.Turns)
	return strings.Join(parts, " ")
}

func mergeRuntimeSummary(previous, current *ExecuteRuntimeSummary) *ExecuteRuntimeSummary {
	if current == nil {
		return previous
	}
	if current.SessionID == "" && previous != nil {
		current.SessionID = previous.SessionID
	}
	return current
}

func hasDiagnosticOnlyCompletion(run pruntime.Result) bool {
	for _, warning := range run.Warnings {
		if strings.Contains(strings.ToLower(warning), "diagnostic-only") {
			return true
		}
	}
	return false
}

func safeArtifactPath(uri string) string {
	if safeRelPath(uri) {
		return uri
	}
	return ""
}

func ptrTime(t time.Time) *time.Time { return &t }

func firstNonEmptyString(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return value
		}
	}
	return "runtime artifact"
}

func mustReadPlan(s Service, sp Sprint) string {
	data, _ := s.store.ReadArtifact(sp, StagePlan)
	return data
}

func executeResultMessage(tasks []ExecuteTaskRecord) string {
	if hasFailedExecuteTask(tasks) {
		return "execute failed"
	}
	return "execute complete"
}

func (s Service) executeModelSelection(override string) ExecuteModelSelection {
	if strings.TrimSpace(override) != "" {
		return ExecuteModelSelection{Model: override, Source: "command override"}
	}
	if rt, ok := s.stageRuntime[StageExecute]; ok && strings.TrimSpace(rt.Model) != "" {
		return ExecuteModelSelection{Model: rt.Model, Source: "planning.execute_model"}
	}
	if rt, ok := s.stageRuntime[StagePlan]; ok && strings.TrimSpace(rt.Model) != "" {
		return ExecuteModelSelection{Model: rt.Model, Source: "planning.plan_model"}
	}
	if model := joinProviderModel(s.runtimeConfig.Provider, s.runtimeConfig.Model); model != "" {
		return ExecuteModelSelection{Model: model, Source: "runtime.config"}
	}
	return ExecuteModelSelection{Model: "unresolved", Source: "unresolved"}
}

func joinProviderModel(provider, model string) string {
	if strings.TrimSpace(model) == "" {
		return ""
	}
	if strings.TrimSpace(provider) == "" {
		return model
	}
	return provider + "/" + model
}

// executeSelectionForTask resolves one task's effective model selection. An
// inline plan annotation wins over the batch selection; defaults stay
// unchanged when no annotation is present.
func executeSelectionForTask(selection ExecuteModelSelection, task ExecutePlanTask) ExecuteModelSelection {
	if model := strings.TrimSpace(task.Model); model != "" {
		return ExecuteModelSelection{Model: model, Source: "plan.md task annotation"}
	}
	return selection
}

func safeExecuteText(key, value string) string {
	return config.RedactValue(key, safeError(fmt.Errorf("%s", value)))
}

func hasFailedExecuteTask(tasks []ExecuteTaskRecord) bool {
	for _, task := range tasks {
		if task.Status == ExecuteTaskFailed || task.Status == ExecuteTaskCancelled {
			return true
		}
	}
	return false
}

func allExecuteTasksResolved(tasks []ExecuteTaskRecord) bool {
	if len(tasks) == 0 {
		return false
	}
	for _, task := range tasks {
		if task.Status != ExecuteTaskComplete && task.Status != ExecuteTaskDeferred {
			return false
		}
	}
	return true
}

package sprint

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"time"
)

func ExecuteRunStatePath(root string, s Sprint) (string, error) {
	return resolveSprintContained(root, s, ExecuteRunStateRelPath(s))
}

func NewExecuteRunState(s Sprint, target ExecuteTargetRef, planPath, planFingerprint string, tasks []ExecuteTaskRecord, now time.Time) ExecuteRunState {
	if now.IsZero() {
		now = time.Now().UTC()
	}
	return ExecuteRunState{
		SchemaVersion:   ExecuteRunStateSchemaVersion,
		Project:         s.Project,
		Sprint:          s.Slug,
		Target:          target,
		PlanPath:        filepath.ToSlash(planPath),
		PlanFingerprint: planFingerprint,
		CreatedAt:       now.UTC(),
		UpdatedAt:       now.UTC(),
		Tasks:           tasks,
	}
}

func LoadExecuteRunState(root string, s Sprint) (ExecuteRunState, error) {
	if state, found, err := loadExecuteStateDatabase(root, s); err != nil {
		return ExecuteRunState{}, err
	} else if found {
		path, pathErr := ExecuteRunStatePath(root, s)
		if pathErr != nil {
			return ExecuteRunState{}, pathErr
		}
		if err := ValidateExecuteRunState(root, s, state, path); err != nil {
			return ExecuteRunState{}, err
		}
		return state, nil
	}
	path, err := ExecuteRunStatePath(root, s)
	if err != nil {
		return ExecuteRunState{}, err
	}
	content, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return ExecuteRunState{}, fmt.Errorf("%w: %s", ErrExecuteRunStateMissing, path)
		}
		return ExecuteRunState{}, fmt.Errorf("read execute run state %s: %w", path, err)
	}
	var state ExecuteRunState
	if err := json.Unmarshal(content, &state); err != nil {
		return ExecuteRunState{}, fmt.Errorf("%w: %s: %w", ErrExecuteRunStateMalformed, path, err)
	}
	if err := ValidateExecuteRunState(root, s, state, path); err != nil {
		return ExecuteRunState{}, err
	}
	return state, nil
}

// legacyTerminalExecuteRunState reports the pre-plan-executor summary shape
// used by older completed sprints. Those files contain no resumable task
// ownership, so startup recovery must leave them untouched instead of making
// the web server unavailable.
func legacyTerminalExecuteRunState(root string, s Sprint) bool {
	_, ok := LegacyTerminalExecuteStatus(root, s)
	return ok
}

// LegacyTerminalExecuteStatus reads the terminal result recorded before
// task-addressable execute state existed. It is historical evidence only and
// is never treated as resumable task ownership.
func LegacyTerminalExecuteStatus(root string, s Sprint) (string, bool) {
	path, err := ExecuteRunStatePath(root, s)
	if err != nil {
		return "", false
	}
	content, err := os.ReadFile(path)
	if err != nil {
		return "", false
	}
	var header struct {
		SchemaVersion int    `json:"schemaVersion"`
		Status        string `json:"status"`
	}
	if err := json.Unmarshal(content, &header); err != nil || header.SchemaVersion != 0 {
		return "", false
	}
	switch header.Status {
	case "complete", "failed", "cancelled":
		return header.Status, true
	default:
		return "", false
	}
}

func SaveExecuteRunState(root string, s Sprint, state ExecuteRunState) error {
	if authoritative, err := ExecuteStateInDatabase(root, s); err != nil {
		return err
	} else if authoritative {
		if err := saveExecuteStateDatabase(root, s, state); err != nil {
			return err
		}
		if !executeStateCheckpoint(state) {
			return nil
		}
		return saveExecuteRunStateWithHooks(root, s, state, atomicWriteHooks{})
	}
	return saveExecuteRunStateWithHooks(root, s, state, atomicWriteHooks{})
}

func executeStateCheckpoint(state ExecuteRunState) bool {
	if len(state.Tasks) == 0 {
		return false
	}
	for _, task := range state.Tasks {
		if !isTerminalExecuteStatus(task.Status) {
			return false
		}
	}
	return true
}

func saveExecuteRunStateWithHooks(root string, s Sprint, state ExecuteRunState, hooks atomicWriteHooks) error {
	path, err := ExecuteRunStatePath(root, s)
	if err != nil {
		return err
	}
	state.UpdatedAt = time.Now().UTC()
	if err := ValidateExecuteRunState(root, s, state, path); err != nil {
		return err
	}
	content, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal execute run state %s: %w", path, err)
	}
	content = append(content, '\n')
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("create execute run state directory %s: %w", filepath.Dir(path), err)
	}
	temp, err := os.CreateTemp(filepath.Dir(path), ".run-state.*.tmp")
	if err != nil {
		return fmt.Errorf("create temporary execute run state %s: %w", path, err)
	}
	tempPath := temp.Name()
	cleanup := true
	defer func() {
		if cleanup {
			_ = os.Remove(tempPath)
		}
	}()
	if _, err := temp.Write(content); err != nil {
		_ = temp.Close()
		return fmt.Errorf("write temporary execute run state %s: %w", tempPath, err)
	}
	if err := temp.Sync(); err != nil {
		_ = temp.Close()
		return fmt.Errorf("flush temporary execute run state %s: %w", tempPath, err)
	}
	if err := temp.Close(); err != nil {
		return fmt.Errorf("close temporary execute run state %s: %w", tempPath, err)
	}
	if hooks.BeforeRename != nil {
		if err := hooks.BeforeRename(path); err != nil {
			return fmt.Errorf("prepare execute run state rename %s: %w", path, err)
		}
	}
	if err := os.Rename(tempPath, path); err != nil {
		return fmt.Errorf("rename execute run state %s: %w", path, err)
	}
	cleanup = false
	syncDir(filepath.Dir(path))
	return nil
}

func ValidateExecuteRunState(root string, s Sprint, state ExecuteRunState, path string) error {
	if state.SchemaVersion == 0 {
		return fmt.Errorf("%w: %s: missing schemaVersion", ErrExecuteRunStateMalformed, path)
	}
	if state.SchemaVersion != ExecuteRunStateSchemaVersion {
		return fmt.Errorf("%w: %s: schemaVersion %d", ErrExecuteRunStateUnsupported, path, state.SchemaVersion)
	}
	if state.Project == "" || state.Sprint == "" || state.Target.Path == "" || state.Target.Source == "" || state.PlanPath == "" || state.PlanFingerprint == "" || state.CreatedAt.IsZero() || state.UpdatedAt.IsZero() {
		return fmt.Errorf("%w: %s: missing required top-level fields", ErrExecuteRunStateMalformed, path)
	}
	if state.Project != s.Project {
		return fmt.Errorf("%w: %s: project mismatch %q", ErrExecuteRunStateMalformed, path, state.Project)
	}
	if state.Sprint != s.Slug {
		return fmt.Errorf("%w: %s: sprint mismatch %q", ErrExecuteRunStateMalformed, path, state.Sprint)
	}
	if !safeRelPath(state.PlanPath) {
		return fmt.Errorf("%w: %s: unsafe planPath", ErrExecuteRunStateMalformed, path)
	}
	if _, err := resolveSprintContained(root, s, state.PlanPath); err != nil {
		return fmt.Errorf("%w: %s: unsafe planPath: %w", ErrExecuteRunStateMalformed, path, err)
	}
	if strings.ContainsAny(state.PlanFingerprint, "\x00\r\n") {
		return fmt.Errorf("%w: %s: unsafe planFingerprint", ErrExecuteRunStateMalformed, path)
	}
	if len(state.Tasks) == 0 {
		return fmt.Errorf("%w: %s: missing tasks", ErrExecuteRunStateMalformed, path)
	}
	seen := map[string]bool{}
	for i, task := range state.Tasks {
		if task.ID == "" || task.Identity.Name == "" || task.CreatedAt.IsZero() || task.UpdatedAt.IsZero() {
			return fmt.Errorf("%w: %s: task %d missing required fields", ErrExecuteRunStateMalformed, path, i)
		}
		if seen[task.ID] {
			return fmt.Errorf("%w: %s: duplicate task id %q", ErrExecuteRunStateMalformed, path, task.ID)
		}
		seen[task.ID] = true
		if strings.ContainsAny(task.ID+task.Identity.Name, "\x00\r\n") {
			return fmt.Errorf("%w: %s: task %d has unsafe identity", ErrExecuteRunStateMalformed, path, i)
		}
		if task.Identity.PlanLine < 1 {
			return fmt.Errorf("%w: %s: task %q has invalid planLine", ErrExecuteRunStateMalformed, path, task.ID)
		}
		if !ValidExecuteTaskStatus(task.Status) {
			return fmt.Errorf("%w: %s: task %q has unsupported status %q", ErrExecuteRunStateMalformed, path, task.ID, task.Status)
		}
		if task.Status == ExecuteTaskDeferred {
			if task.CompletedAt == nil {
				return fmt.Errorf("%w: %s: deferred task %q has no completion time", ErrExecuteRunStateMalformed, path, task.ID)
			}
			hasReason := false
			for _, diagnostic := range task.Diagnostics {
				if diagnostic.Code == "deferred" && strings.TrimSpace(diagnostic.Message) != "" {
					hasReason = true
					break
				}
			}
			if !hasReason {
				return fmt.Errorf("%w: %s: deferred task %q has no rationale", ErrExecuteRunStateMalformed, path, task.ID)
			}
		}
		if task.Attempts < 0 {
			return fmt.Errorf("%w: %s: task %q has invalid attempts", ErrExecuteRunStateMalformed, path, task.ID)
		}
		if task.Status == ExecuteTaskRunning && task.StartedAt == nil {
			return fmt.Errorf("%w: %s: running task %q missing startedAt", ErrExecuteRunStateMalformed, path, task.ID)
		}
		if isTerminalExecuteStatus(task.Status) && task.CompletedAt == nil {
			return fmt.Errorf("%w: %s: terminal task %q missing completedAt", ErrExecuteRunStateMalformed, path, task.ID)
		}
		for j, diagnostic := range task.Diagnostics {
			if diagnostic.Code == "" || diagnostic.Message == "" || diagnostic.At.IsZero() || strings.ContainsAny(diagnostic.Code+diagnostic.Message, "\x00\r\n") {
				return fmt.Errorf("%w: %s: task %q diagnostic %d invalid", ErrExecuteRunStateMalformed, path, task.ID, j)
			}
		}
		for j, evidence := range task.Evidence {
			if evidence.Kind == "" || evidence.Summary == "" || strings.ContainsAny(evidence.Kind+evidence.Summary, "\x00\r\n") {
				return fmt.Errorf("%w: %s: task %q evidence %d invalid", ErrExecuteRunStateMalformed, path, task.ID, j)
			}
			if evidence.Path != "" && !safeRelPath(evidence.Path) {
				return fmt.Errorf("%w: %s: task %q evidence %d has unsafe path", ErrExecuteRunStateMalformed, path, task.ID, j)
			}
		}
	}
	return nil
}

func isTerminalExecuteStatus(status ExecuteTaskStatus) bool {
	return status == ExecuteTaskComplete || status == ExecuteTaskDeferred || status == ExecuteTaskFailed || status == ExecuteTaskCancelled
}

func safeRelPath(path string) bool {
	if path == "" || filepath.IsAbs(path) {
		return false
	}
	clean := filepath.ToSlash(filepath.Clean(filepath.FromSlash(path)))
	return clean != "." && !strings.HasPrefix(clean, "../") && !strings.Contains(clean, "\x00")
}

