		trace := sha256.Sum256([]byte(project + "\x00" + sprint + "\x00" + stage + "\x00" + checksum + "\x00" + s.now().UTC().Format(time.RFC3339Nano)))
		req.TraceID = hex.EncodeToString(trace[:16])
